-- One row per calendar date.
-- DATE_KEY is an integer YYYYMMDD, generated by a future dbt model/seed.

CREATE TABLE IF NOT EXISTS CHICAGO_311_DEV.GOLD.DIM_DATE (
    DATE_KEY                NUMBER(8, 0) NOT NULL,
    CALENDAR_DATE           DATE NOT NULL,
    CALENDAR_YEAR           NUMBER(4, 0),
    CALENDAR_QUARTER        NUMBER(1, 0),
    CALENDAR_MONTH          NUMBER(2, 0),
    MONTH_NAME              VARCHAR(20),
    WEEK_OF_YEAR            NUMBER(2, 0),
    DAY_OF_MONTH            NUMBER(2, 0),
    DAY_OF_WEEK_ISO         NUMBER(1, 0),
    DAY_NAME                VARCHAR(20),
    IS_WEEKEND              BOOLEAN,
    CONSTRAINT PK_DIM_DATE PRIMARY KEY (DATE_KEY)
)
COMMENT = 'Calendar dates for created and closed service-request events';
